<?php
/* SmartToolz Admin Analytics - deep data panel */
declare(strict_types=1);

$anQ = function(string $sql, array $params = []) use ($db): array {
    try { $q=$db->prepare($sql); $q->execute($params); return $q->fetchAll(PDO::FETCH_ASSOC); }
    catch (Throwable $e) { return []; }
};
$anOne = function(string $sql, array $params = []) use ($db): int {
    try { $q=$db->prepare($sql); $q->execute($params); return (int)$q->fetchColumn(); }
    catch (Throwable $e) { return 0; }
};
$anCol = function(string $table,string $column) use ($db): bool {
    try { $q=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?"); $q->execute([$table,$column]); return (bool)$q->fetchColumn(); }
    catch(Throwable $e){ return false; }
};
$S=[];
$S['users']=$anOne("SELECT COUNT(*) FROM creator_users");
$S['admins']=$anOne("SELECT COUNT(*) FROM creator_users WHERE role IN ('admin','superadmin')");
$S['v0']=$anOne("SELECT COUNT(*) FROM analytics_visitors WHERE first_seen>=CURDATE()");
$S['v7']=$anOne("SELECT COUNT(*) FROM analytics_visitors WHERE first_seen>=DATE_SUB(NOW(),INTERVAL 7 DAY)");
$S['v30']=$anOne("SELECT COUNT(*) FROM analytics_visitors WHERE first_seen>=DATE_SUB(NOW(),INTERVAL 30 DAY)");
$S['p0']=$anOne("SELECT COUNT(*) FROM analytics_pageviews WHERE viewed_at>=CURDATE()");
$S['p7']=$anOne("SELECT COUNT(*) FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)");
$S['p30']=$anOne("SELECT COUNT(*) FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)");
$S['live']=$anOne("SELECT COUNT(*) FROM analytics_live WHERE last_seen>=DATE_SUB(NOW(),INTERVAL 2 MINUTE)");
$S['e0']=$anOne("SELECT COUNT(*) FROM analytics_events WHERE viewed_at>=CURDATE()");
$S['u0']=$anOne("SELECT COUNT(*) FROM tool_usage WHERE created_at>=CURDATE()");
$S['d0']=$anOne("SELECT COUNT(*) FROM download_tracking WHERE created_at>=CURDATE()");
$S['u7']=$anOne("SELECT COUNT(*) FROM tool_usage WHERE created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)");
$S['d7']=$anOne("SELECT COUNT(*) FROM download_tracking WHERE created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY)");
$S['credits']=$anOne("SELECT COALESCE(SUM(GREATEST(credits,0)),0) FROM creator_users");

$hour=$anQ("SELECT DATE_FORMAT(viewed_at,'%H:00') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR) GROUP BY HOUR(viewed_at),DATE(viewed_at),DATE_FORMAT(viewed_at,'%H:00') ORDER BY MIN(viewed_at)");
$day=$anQ("SELECT DATE_FORMAT(viewed_at,'%b %d') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY DATE(viewed_at),DATE_FORMAT(viewed_at,'%b %d') ORDER BY MIN(viewed_at)");
$dayV=$anQ("SELECT DATE_FORMAT(first_seen,'%b %d') label,COUNT(*) total FROM analytics_visitors WHERE first_seen>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY DATE(first_seen),DATE_FORMAT(first_seen,'%b %d') ORDER BY MIN(first_seen)");
$pages=$anQ("SELECT COALESCE(NULLIF(page_path,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY page_path ORDER BY total DESC LIMIT 20");
$countries=$anQ("SELECT COALESCE(NULLIF(country,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY country ORDER BY total DESC LIMIT 20");
$cities=$anQ("SELECT COALESCE(NULLIF(city,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY city ORDER BY total DESC LIMIT 20");
$devices=$anQ("SELECT COALESCE(NULLIF(device,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY device ORDER BY total DESC LIMIT 15");
$browsers=$anQ("SELECT COALESCE(NULLIF(browser,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY browser ORDER BY total DESC LIMIT 15");
$tools=$anQ("SELECT COALESCE(NULLIF(tool_name,''),'Unknown') label,COUNT(*) total FROM tool_usage WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY tool_name ORDER BY total DESC LIMIT 20");
$downloads=$anQ("SELECT COALESCE(NULLIF(tool_name,''),'Unknown') label,COUNT(*) total FROM download_tracking WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY tool_name ORDER BY total DESC LIMIT 20");
$events=$anQ("SELECT COALESCE(NULLIF(event_name,''),'Unknown') label,COUNT(*) total FROM analytics_events WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY event_name ORDER BY total DESC LIMIT 20");
$live=$anQ("SELECT visitor_id,country_code,country,city,device,browser,page_path,last_seen FROM analytics_live WHERE last_seen>=DATE_SUB(NOW(),INTERVAL 2 MINUTE) ORDER BY last_seen DESC LIMIT 200");
$recent=$anQ("SELECT page_path,viewed_at FROM analytics_pageviews ORDER BY viewed_at DESC LIMIT 20");
$ref=$anCol('analytics_pageviews','referrer')?$anQ("SELECT COALESCE(NULLIF(referrer,''),'Direct / None') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY referrer ORDER BY total DESC LIMIT 20"):[];
$lang=$anCol('analytics_pageviews','language')?$anQ("SELECT COALESCE(NULLIF(language,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY language ORDER BY total DESC LIMIT 20"):[];
$os=$anCol('analytics_pageviews','os')?$anQ("SELECT COALESCE(NULLIF(os,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY os ORDER BY total DESC LIMIT 20"):[];
$screen=$anCol('analytics_pageviews','screen')?$anQ("SELECT COALESCE(NULLIF(screen,''),'Unknown') label,COUNT(*) total FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY screen ORDER BY total DESC LIMIT 20"):[];
$mx=static fn(array $r):int=>max(1,max(array_map(static fn($x)=>(int)$x['total'],$r?:[['total'=>1]])));
$mh=$mx($hour);$md=$mx($day);$mv=$mx($dayV);$mp=$mx($pages);$mc=$mx($countries);$mt=$mx($tools);
?>
