ackground:#635bff}.ga-two{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-top:9px}.ga-map{height:245px;border:1px solid #e5e9ef;border-radius:12px;background:radial-gradient(circle at 25% 35%,#d9deff 0 2px,transparent 3px),radial-gradient(circle at 51% 48%,#d9deff 0 2px,transparent 3px),radial-gradient(circle at 72% 32%,#d9deff 0 2px,transparent 3px),radial-gradient(circle at 64% 70%,#d9deff 0 2px,transparent 3px),linear-gradient(180deg,#f8faff,#eef3fa);position:relative}.ga-map:before{content:'🌍';position:absolute;inset:0;display:grid;place-items:center;font-size:95px;opacity:.13}.ga-table{width:100%;border-collapse:collapse;font-size:9px}.ga-table-wrap{max-height:370px;overflow:auto;border:1px solid #edf0f4;border-radius:10px}.ga-table th,.ga-table td{padding:7px;border-bottom:1px solid #edf0f4;text-align:left;vertical-align:top}.ga-table th{position:sticky;top:0;background:#fafbfe;color:#596477}.ga-dot{display:inline-flex;align-items:center;gap:4px;color:#168551;font-weight:900}.ga-dot:before{content:'';width:6px;height:6px;border-radius:50%;background:#18a55d}.ga-search input{width:100%;padding:8px 10px;border:1px solid #dde3eb;border-radius:8px;font-size:10px}.ga-note{padding:9px;background:#f8f9fc;border:1px solid #e9ecf1;border-radius:9px;color:#687486;font-size:9px;line-height:1.55}.ga-actions{display:flex;flex-wrap:wrap;gap:6px}.ga-link{padding:8px 10px;background:#eef0f5;border-radius:8px;font-size:9px;font-weight:900;color:#455066}.ga-link.primary{background:#635bff;color:#fff}.ga-chip{display:inline-block;padding:4px 7px;margin:2px;border-radius:999px;background:#f0f2f6;font-size:8px;color:#596477;font-weight:900}
