<script>
(()=>{const root=document.getElementById('smarttoolz-ga');if(!root)return;const tabs=[...root.querySelectorAll('.ga-tab')],panes=[...root.querySelectorAll('.ga-pane')];tabs.forEach(b=>b.addEventListener('click',()=>{tabs.forEach(x=>x.classList.remove('active'));panes.forEach(x=>x.classList.remove('active'));b.classList.add('active');root.querySelector('[data-pane="'+b.dataset.tab+'"]')?.classList.add('active')}));const tbody=document.getElementById('gaLiveRows'),search=document.getElementById('gaSearch'),badge=document.getElementById('gaLiveCount'),kpi=document.getElementById('gaLiveKpi');let cache=[];const esc=s=>String(s??'').replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\\':'&#92;'}[m]));function render(list){if(!tbody)return;tbody.innerHTML=list.map(r=>`<tr><td><span class="ga-dot">LIVE</span></td><td>${esc(r.visitor_id||'-')}</td><td>${esc((r.country_code||'')+' '+(r.country||'')+' '+(r.city||''))}</td><td>${esc(r.device||'Unknown')}</td><td>${esc(r.browser||'Unknown')}</td><td>${esc(r.page_path||'-')}</td><td>${esc(r.last_seen||'-')}</td></tr>`).join('');if(badge)badge.textContent=list.length.toLocaleString();if(kpi)kpi.textContent=list.length.toLocaleString()}function filter(){const q=(search?.value||'').toLowerCase();render(cache.filter(x=>JSON.stringify(x).toLowerCase().includes(q)))}search?.addEventListener('input',filter);async function liveRefresh(){try{const r=await fetch('/analytics/live.php?_='+Date.now(),{cache:'no-store',credentials:'same-origin'});const d=await r.json();if(d.ok){cache=d.visitors||[];filter()}}catch(e){}}liveRefresh();setInterval(liveRefresh,1000)})();
</script>
